function WorldRenderer.prototype.drawMover(self, d, p, time)
    local m = p.mover
    if m == nil then
        return
    end
    local mv = moverOffset(m, time)
    local x = m.ax + mv.ox
    local y = m.ay + mv.oy
    do
        local i = 0
        while i < 8 do
            local t0 = i / 8 + 0.02
            local t1 = t0 + 0.06
            seg(
                d,
                m.ax + (m.bx - m.ax) * t0 + p.w / 2,
                m.ay + (m.by - m.ay) * t0 + p.h / 2,
                m.ax + (m.bx - m.ax) * t1 + p.w / 2,
                m.ay + (m.by - m.ay) * t1 + p.h / 2,
                2,
                PAPER_DIM
            )
            i = i + 1
        end
    end
    d:drawPolygon(
        {
            Vec2(x, y + p.h),
            Vec2(x + p.w, y + p.h),
            Vec2(x + p.w, y + 2),
            Vec2(x, y + 2)
        },
        col(ink(52, 60, 58, 230)),
        0,
        Color(0, 0, 0, 0)
    )
    seg(
        d,
        x + 2,
        y + p.h - 1,
        x + p.w - 2,
        y + p.h - 1,
        1.8,
        PAPER_DIM
    )
    dot(
        d,
        x + p.w / 2,
        y + p.h / 2,
        4 + math.sin(time * 3) * 1,
        GOLD,
        0.85
    )
end
