function WorldRenderer.prototype.updateHeroSprite(self, x, y, facing, pose, t, phaseIndex, visible)
    local sp = self.heroSprite
    local f = self.heroFxDraw
    f:clear()
    if sp == nil or not visible then
        if sp ~= nil then
            sp.visible = false
        end
        return
    end
    sp.visible = true
    local bob = 0
    if pose == "idle" then
        bob = math.sin(t * 2) * 1.6
    elseif pose == "run" then
        bob = -math.abs(math.sin(t * 12)) * 2.2
    elseif pose == "jump" then
        bob = 2.5
    elseif pose == "fall" then
        bob = -1.5
    end
    sp.position = Vec2(x, y + bob)
    sp.scaleX = self.heroScale * facing
    sp.scaleY = self.heroScale
    local moonK = clamp01(1 - math.abs(phaseIndex - 4) / 4)
    dot(
        f,
        x,
        y + 44,
        30,
        Palette.moonWhite,
        0.05 + 0.08 * moonK
    )
    if pose == "attack1" or pose == "attack2" or pose == "attack3" then
        local idx = pose == "attack1" and 0 or (pose == "attack2" and 1 or 2)
        local p = clamp01(t / ATTACK_TIME[idx + 1])
        local shX = x + facing * 4
        local shY = y + 56 + bob
        local a0 = facing > 0 and -0.7 or math.pi + 0.7
        local a1 = a0 + facing * (0.6 + p * 1.9)
        arc(
            f,
            shX,
            shY,
            54,
            a0,
            a1,
            12,
            2.4,
            Palette.white,
            0.55 * (1 - p * 0.35)
        )
        arc(
            f,
            shX,
            shY,
            44,
            a0,
            a1,
            10,
            1.6,
            Palette.white,
            0.32 * (1 - p)
        )
    end
    if pose == "hurt" then
        dot(
            f,
            x,
            y + 46,
            26,
            ink(220, 70, 60, 160),
            0.5
        )
    end
end
function WorldRenderer.prototype.heroPose(self, p)
    if p.onLadder then
        return "ladder"
    end
    local a = p.anim
    if a == "wallslide" then
        return "cling"
    end
    if a == "climb" then
        return "ladder"
    end
    if a == "attack" then
        local idx = p.attackIndex
        return idx <= 0 and "attack1" or (idx == 1 and "attack2" or "attack3")
    end
    if a == "land" then
        return "idle"
    end
    return a
end
